select * from jsonb_populate_recordset(
  null::public.questions,
  $questions$[{"id":"de4a9aad-7eb9-4e75-93db-005aa569bf77","q_id":"CR_01","prompt":"Have you estimated how long you can operate without income?","weight":1,"version":"v1","industry":"generic","sequence":1,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":false,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"Without runway clarity, the candidate cannot judge pressure, timing, or survival risk.","dimension_code":"cash_reality","action_required":"Document personal cash runway and assumptions.","constraint_label":"Cash runway not proven","diagnostic_depth":"core","retest_condition":"Retest when the candidate can show a written runway estimate.","evidence_required":"Written cash runway estimate and assumptions.","failure_condition":"The candidate has not proven a realistic personal cash runway.","hard_fail_message":"Readiness stop: cash runway is not proven.","source_reference_id":null,"requirement_to_proceed":"The candidate needs a written cash runway estimate with realistic assumptions.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"7e0b9eb2-67a9-4e62-a3b0-374fd9e1af58","q_id":"CR_02","prompt":"Do you know the minimum resources required to start?","weight":1,"version":"v1","industry":"generic","sequence":2,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":false,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"Without resource clarity, the candidate is guessing at the minimum conditions required to start.","dimension_code":"cash_reality","action_required":"Document minimum startup requirements.","constraint_label":"Startup resources unclear","diagnostic_depth":"core","retest_condition":"Retest when minimum startup resources are documented.","evidence_required":"Minimum resource list covering cash, tools, supplies, labour, and time.","failure_condition":"The candidate has not defined the minimum resources required to start safely.","hard_fail_message":"Readiness stop: minimum startup resources are not defined.","source_reference_id":null,"requirement_to_proceed":"The candidate needs a minimum resource list covering cash, tools, supplies, labour, and time.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"bd7bd81e-1d9b-49e7-b6e2-271ce6bffc89","q_id":"EL_01","prompt":"Can you clearly explain how this business makes money?","weight":1,"version":"v1","industry":"generic","sequence":3,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":false,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"If the candidate cannot explain the money model, decisions will be based on hope rather than economics.","dimension_code":"economic_literacy","action_required":"Clarify the revenue, cost, margin, and repeat-work logic.","constraint_label":"Money model unclear","diagnostic_depth":"core","retest_condition":"Retest when the candidate can explain the money model simply and coherently.","evidence_required":"Plain-language money model covering revenue, cost, margin, and repeat work.","failure_condition":"The candidate cannot clearly explain the money model.","hard_fail_message":"Readiness stop: the money model is unclear.","source_reference_id":null,"requirement_to_proceed":"The candidate needs to explain simply how revenue, costs, margin, and repeat work create profit.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"370539a6-a3b0-4314-a3e2-8e8c7f1388e0","q_id":"EL_02","prompt":"Have you identified your main cost drivers?","weight":1,"version":"v1","industry":"generic","sequence":4,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":true,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"If the candidate does not understand cost drivers, margin and cash judgement will be weak.","dimension_code":"economic_literacy","action_required":"Define the main cost drivers and margin pressure points.","constraint_label":"Cost drivers unclear","diagnostic_depth":"core","retest_condition":"Retest when the candidate can identify and explain the main cost drivers.","evidence_required":"List of main cost drivers and margin pressure points.","failure_condition":"The candidate has not identified the main cost drivers.","hard_fail_message":"Readiness stop: cost drivers are unclear.","source_reference_id":null,"requirement_to_proceed":"The candidate needs to identify the main costs that control margin and cash pressure.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"f699160c-c22a-4c0f-926a-95534daa949d","q_id":"MR_01","prompt":"What evidence do you have that customers will pay for this?","weight":1,"version":"v1","industry":"generic","sequence":5,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":false,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"Interest is not payment evidence. Assumption is not demand.","dimension_code":"market_reality","action_required":"Collect real customer payment or commitment evidence.","constraint_label":"Customer payment evidence missing","diagnostic_depth":"core","retest_condition":"Retest when the candidate has evidence from real customer behaviour, payment, or commitment.","evidence_required":"Payment, signed commitment, booking, deposit, or equivalent customer evidence.","failure_condition":"The candidate has not shown real evidence that customers will pay.","hard_fail_message":"Readiness stop: customer payment evidence is missing.","source_reference_id":null,"requirement_to_proceed":"The candidate needs real-world evidence of willingness to pay.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"3112c758-4b4d-4dcb-bdb2-3b36677c6626","q_id":"MR_02","prompt":"Have you clearly defined your target customer?","weight":1,"version":"v1","industry":"generic","sequence":6,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":false,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"A vague customer creates vague action, vague offers, and weak evidence.","dimension_code":"market_reality","action_required":"Define the target customer, problem, offer, and buying reason.","constraint_label":"Target customer unclear","diagnostic_depth":"core","retest_condition":"Retest when the candidate can define the target customer precisely.","evidence_required":"Defined customer profile, problem, offer, and buying reason.","failure_condition":"The candidate has not clearly defined the target customer.","hard_fail_message":"Readiness stop: target customer is unclear.","source_reference_id":null,"requirement_to_proceed":"The candidate needs a clear customer type, problem, offer, and buying reason.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"3de66481-cb96-4061-ab51-15f03b7e4597","q_id":"OP_01","prompt":"Do you have the operational ability to deliver your product or service consistently?","weight":1,"version":"v1","industry":"generic","sequence":7,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":true,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"If delivery capability is unproven, the candidate cannot be trusted to execute consistently.","dimension_code":"operational_capacity","action_required":"Test delivery capability under realistic conditions.","constraint_label":"Delivery capability unproven","diagnostic_depth":"core","retest_condition":"Retest after the candidate has tested delivery under realistic conditions.","evidence_required":"Evidence from delivery test, trial job, prototype delivery, or equivalent proof.","failure_condition":"The candidate has not proven consistent delivery capability.","hard_fail_message":"Readiness stop: delivery capability is unproven.","source_reference_id":null,"requirement_to_proceed":"The candidate needs evidence that delivery can be performed consistently to the required standard.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"6ce5b340-c2d1-43cc-aa14-1cea63c7ea9f","q_id":"EX_01","prompt":"Have you taken any concrete action toward this business?","weight":1,"version":"v1","industry":"generic","sequence":8,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":true,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"Without action, there is no behavioural evidence to assess.","dimension_code":"execution_discipline","action_required":"Take concrete action that produces evidence.","constraint_label":"Execution evidence missing","diagnostic_depth":"core","retest_condition":"Retest after concrete action has produced evidence.","evidence_required":"Concrete action log with evidence produced.","failure_condition":"The candidate has not taken concrete action that produces evidence.","hard_fail_message":"Readiness stop: execution evidence is missing.","source_reference_id":null,"requirement_to_proceed":"The candidate needs verifiable action toward customers, delivery, or validation.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"537948d6-b596-4a77-ab6a-89412cec5d5a","q_id":"EX_02","prompt":"Can you commit consistent time to this for the next 30 days?","weight":1,"version":"v1","industry":"generic","sequence":9,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":false,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"Without protected time, intention will collapse into drift.","dimension_code":"execution_discipline","action_required":"Create and protect a 30-day execution rhythm.","constraint_label":"Execution rhythm uncommitted","diagnostic_depth":"core","retest_condition":"Retest after the candidate demonstrates a protected execution rhythm.","evidence_required":"30-day execution schedule or activity record.","failure_condition":"The candidate has not committed a realistic 30-day execution rhythm.","hard_fail_message":"Readiness stop: execution rhythm is not committed.","source_reference_id":null,"requirement_to_proceed":"The candidate needs a realistic 30-day work rhythm they can protect.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"c47e1175-ed27-46a2-84ad-f8617ba4bd9d","q_id":"PR_01","prompt":"Are you prepared to persist through uncertainty and repeated failure without changing direction prematurely?","weight":1,"version":"v1","industry":"generic","sequence":10,"is_active":true,"created_at":"2026-05-14T06:50:19.251048","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":false,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"Uncertainty and setbacks expose whether the candidate can keep executing.","dimension_code":"psychological_resilience","action_required":"Demonstrate sustained effort despite uncertainty.","constraint_label":"Resilience under uncertainty unproven","diagnostic_depth":"core","retest_condition":"Retest after the candidate maintains effort despite uncertainty or setbacks.","evidence_required":"Evidence of continued execution after setbacks or uncertainty.","failure_condition":"The candidate has not demonstrated readiness for uncertainty and setbacks.","hard_fail_message":"Readiness stop: resilience under uncertainty is unproven.","source_reference_id":null,"requirement_to_proceed":"The candidate needs evidence of sustained effort under uncertainty.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"fb8b0101-ce72-4126-995c-1bc2ecd12b6c","q_id":"OP_02","prompt":"Can you write down the steps, tools, and supplies needed to do the job the same way each time?","weight":1,"version":"v1","industry":"generic","sequence":11,"is_active":true,"created_at":"2026-05-23T02:58:06.213524","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":false,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"If the process is not documented, repeatability is still dependent on memory and improvisation.","dimension_code":"operational_capacity","action_required":"Document and review a repeatable delivery process.","constraint_label":"Repeatable delivery process undocumented","diagnostic_depth":"core","retest_condition":"Retest when a repeatable delivery process is documented and reviewed.","evidence_required":"Documented delivery process, tools, supplies, and quality checklist.","failure_condition":"The candidate has not documented a repeatable delivery process.","hard_fail_message":"Readiness stop: repeatable delivery process is undocumented.","source_reference_id":null,"requirement_to_proceed":"The candidate needs documented steps, tools, supplies, and quality checks for repeatable delivery.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null},{"id":"046efa8b-de9f-49a9-8beb-f0168b7331b7","q_id":"PR_02","prompt":"Can you keep doing the important work even when you are tired, unsure, or not getting quick results?","weight":1,"version":"v1","industry":"generic","sequence":12,"is_active":true,"created_at":"2026-05-23T02:58:06.213524","updated_at":"2026-07-03T22:59:59.724989","sleeve_code":"core","is_hard_fail":false,"question_set":"quick_gate","scenario_code":"startup","constraint_why":"Slow results and discomfort reveal whether the candidate has execution durability.","dimension_code":"psychological_resilience","action_required":"Track consistent execution over time.","constraint_label":"Consistency under discomfort unproven","diagnostic_depth":"core","retest_condition":"Retest when the candidate can show consistent execution over time.","evidence_required":"Consistent execution record despite low motivation, fatigue, uncertainty, or slow results.","failure_condition":"The candidate has not demonstrated consistency when motivation is low or results are slow.","hard_fail_message":"Readiness stop: consistency under discomfort is unproven.","source_reference_id":null,"requirement_to_proceed":"The candidate needs evidence of consistent execution over time despite discomfort or slow results.","retest_condition_non_fail":null,"requirement_to_proceed_non_fail":null}]$questions$::jsonb
